python3 - <<'PY'
import re
lines=open('/workspace/text.gcode').read().splitlines()
obj=None; block=0
data=[]
cur={'obj':None,'z':[],'x':[],'y':[],'ext':0,'start':0,'end':0}
def flush():
    if cur['obj'] is not None and (cur['z'] or cur['x']):
        data.append((cur['obj'], cur['start'], cur['end'], min(cur['z']) if cur['z'] else None, max(cur['z']) if cur['z'] else None, min(cur['x']) if cur['x'] else None, max(cur['x']) if cur['x'] else None, min(cur['y']) if cur['y'] else None, max(cur['y']) if cur['y'] else None, cur['ext']))
for i,l in enumerate(lines,1):
    if l.startswith('M486 S0'):
        flush(); cur={'obj':'text','z':[],'x':[],'y':[],'ext':0,'start':i,'end':i}
    elif l.startswith('M486 S1'):
        flush(); cur={'obj':'box','z':[],'x':[],'y':[],'ext':0,'start':i,'end':i}
    elif l.startswith('M486 S-1'):
        flush(); cur={'obj':None,'z':[],'x':[],'y':[],'ext':0,'start':i,'end':i}
    elif cur['obj']:
        if l.startswith('G1') or l.startswith('G0'):
            for k,pat in [('x',r'X([-\d.]+)'),('y',r'Y([-\d.]+)'),('z',r'Z([-\d.]+)')]:
                m=re.search(pat,l)
                if m: cur[k].append(float(m.group(1)))
            m=re.search(r' E([-\d.]+)',l)
            if m: cur['ext']+=float(m.group(1))
flush()
print('blocks',len(data))
for d in data:
    if d[0]=='text':
        print(d[:9], 'ext%.2f'%d[9])
