python3 - <<'PY'
import re,collections
lines=open('/workspace/text.gcode').read().splitlines()
obj=None; z=None
rows=collections.defaultdict(lambda:{'x':[],'y':[],'n':0,'e':0})
curz=0
for i,l in enumerate(lines,1):
    if l.startswith('M486 S0'): obj='text'
    elif l.startswith('M486 S1'): obj='box'
    elif l.startswith('M486 S-1'): obj=None
    if obj=='text' and (l.startswith('G1') or l.startswith('G0')):
        mz=re.search(r'Z([-\d.]+)',l)
        if mz: curz=float(mz.group(1))
        mx=re.search(r'X([-\d.]+)',l); my=re.search(r'Y([-\d.]+)',l)
        if mx or my:
            d=rows[round(curz,3)]
            if mx:d['x'].append(float(mx.group(1)))
            if my:d['y'].append(float(my.group(1)))
            d['n']+=1
        me=re.search(r' E([-\d.]+)',l)
        if me: rows[round(curz,3)]['e']+=float(me.group(1))
for z in sorted(rows):
    d=rows[z]
    if d['x']:
        print(f"z={z:7.3f} n={d['n']:4d} e={d['e']:8.2f} x=[{min(d['x']):7.2f},{max(d['x']):7.2f}] y=[{min(d['y']):7.2f},{max(d['y']):7.2f}]")
PY

